// MIT. DOM-only rendering; no cookies, storage, CDN dependencies or automatic API calls.
import { buildUnpaidRequest, readLimitedResponse, decodePaymentRequired } from './request.mjs';
const $ = id => document.getElementById(id);
const text = (id, value) => { $(id).textContent = value; };
const json = value => JSON.stringify(value, null, 2);
const bodyMethods = new Set(['POST', 'PUT', 'PATCH']);
let documentSpec, operations = [], current, request, controller, revision = 0;
const setError = value => { text('input-error', value); $('input-error').hidden = !value; };
function invalidate() {
  revision++; controller?.abort(); controller = null;
  $('cancel').hidden = true; $('send').disabled = false; $('result').hidden = true;
}
function values() {
  return { path: Object.fromEntries([...$('path-fields').querySelectorAll('input')].map(input => [input.dataset.parameter, input.value])),
    query: JSON.parse($('query').value), body: $('body').value };
}
function preview() {
  invalidate();
  try {
    if (current['x-x402-payment-required'].extensions.bazaar.info.input.bodyType==='form-data') {
      request=null;setError('');$('copy').disabled=true;$('send').disabled=true;
      text('target',current['x-x402-payment-required'].resource.url);
      text('curl','Prepare and review a private file request in the API merchant workspace, or use SF88 --prepare --form-file with --form-out. The resulting body file retains its exact multipart boundary.');
      text('client-code',"// Read the retained body and Content-Type from your private buyer review.\n"+
        "const request = buildRequest("+JSON.stringify(current.operationId)+", {\n"+
        "  multipart: {body: retainedBytes, contentType: retainedContentType},\n"+
        "  // Include this operation's path and query values when declared.\n"+
        "}, {intentId: 'stable-business-operation-id', acceptIndex: 0, maxAtomic: 'YOUR_LIMIT'});\n"+
        "// Supply the original merchant ticket header when this operation requires it.\n"+
        "// Pass the request to your existing buyer approval and signer.");
      return;
    }
    request = buildUnpaidRequest(current, values(), location.origin);
    text('curl', request.curl); text('target', request.url); setError('');
    const inputs = values();
    const clientInputs = { ...(Object.keys(inputs.path).length ? { path: inputs.path } : {}),
      ...(Object.keys(inputs.query).length ? { query: inputs.query } : {}),
      ...(bodyMethods.has(current['x-seller-route'].method) ? { body: JSON.parse(inputs.body) } : {}) };
    const choice = $('client-payment-option').value;
    if (choice === '') text('client-code', 'Choose an original payment option to generate client usage.');
    else text('client-code', "import { buildRequest } from './seller-client.mjs';\n\n" +
      'const request = buildRequest(' + JSON.stringify(current.operationId) + ', ' + json(clientInputs) + ', {\n' +
      "  intentId: 'your-stable-business-operation-id',\n" +
      '  acceptIndex: ' + Number(choice) + ',\n' +
      '  maxAtomic: ' + JSON.stringify(current['x-x402-payment-required'].accepts[Number(choice)].amount) + ',\n});\n' +
      '// Pass request to your configured buyer with your approval and signer.');
    $('copy').disabled = false; $('send').disabled = false;
  } catch (error) {
    request = null; text('curl', 'Complete valid request inputs to generate a command.'); text('target', '—');
    text('client-code', 'Complete valid request inputs to generate client usage.');
    setError(error.message); $('copy').disabled = true; $('send').disabled = true;
  }
}
function renderPaymentOptions(target, accepts) {
  const container = $(target); container.replaceChildren();
  if (!Array.isArray(accepts) || !accepts.length) {
    const empty = document.createElement('p'); empty.className = 'hint';
    empty.textContent = 'No payment options were provided.'; container.append(empty); return 0;
  }
  const value = item => item === undefined ? 'Not provided' : typeof item === 'string' ? item : json(item);
  const known = new Set(['scheme', 'network', 'amount', 'asset', 'payTo', 'maxTimeoutSeconds', 'extra']);
  for (const [index, terms] of accepts.entries()) {
    const option = document.createElement('section'); option.className = 'payment-option';
    option.setAttribute('aria-label', `Payment option ${index + 1}`);
    const heading = document.createElement('div'); heading.className = 'payment-option-heading';
    const title = document.createElement('h4'); title.textContent = `Option ${index + 1}`;
    heading.append(title); option.append(heading);
    if (!terms || typeof terms !== 'object' || Array.isArray(terms)) {
      const raw = document.createElement('pre'); raw.textContent = value(terms);
      option.append(raw); container.append(option); continue;
    }
    const amount = document.createElement('strong'); amount.textContent = value(terms.amount);
    const unit = document.createElement('small');
    unit.textContent = terms.scheme === 'upto' ? 'atomic units · authorization ceiling' :
      terms.scheme === 'exact' ? 'atomic units / request' : 'atomic units · advertised amount';
    const price = document.createElement('div'); price.className = 'payment-option-price';
    price.append(amount, unit); heading.append(price);
    const fields = document.createElement('dl');
    for (const [label, content] of [
      ['Network', terms.network], ['Scheme', terms.scheme], ['Asset', terms.asset],
      ['Recipient', terms.payTo], ['Timeout (seconds)', terms.maxTimeoutSeconds],
    ]) {
      const name = document.createElement('dt'); name.textContent = label;
      const detail = document.createElement('dd'); detail.textContent = value(content);
      fields.append(name, detail);
    }
    option.append(fields);
    const additional = Object.fromEntries(Object.entries(terms).filter(([key]) => !known.has(key)));
    for (const [label, content] of [
      ['Additional terms (extra)', terms.extra],
      ['Other original fields', Object.keys(additional).length ? additional : undefined],
    ]) {
      if (content === undefined) continue;
      const name = document.createElement('p'); name.className = 'payment-option-extra-label'; name.textContent = label;
      const raw = document.createElement('pre'); raw.className = 'payment-option-extra'; raw.textContent = json(content);
      option.append(name, raw);
    }
    container.append(option);
  }
  return accepts.length;
}
function optionCount(count) { return `${count} option${count === 1 ? '' : 's'}`; }
function choose(operation) {
  current = operation; invalidate();
  const route = operation['x-seller-route'], offer = operation['x-x402-payment-required'];
  const input = offer.extensions.bazaar.info.input;
  text('method', route.method); text('path', route.path); text('description', operation.summary);
  text('payment-options-count', optionCount(renderPaymentOptions('payment-options', offer.accepts)));
  text('schema', json(offer.extensions.bazaar.schema)); text('offer', json(offer));
  text('projection-note', (documentSpec['x-schema-projection-notes'] ?? []).filter(note => note.startsWith(route.id + ':')).join('\n'));
  $('path-fields').replaceChildren();
  for (const name of route.path.split('/').filter(segment => segment.startsWith(':')).map(segment => segment.slice(1))) {
    const label = document.createElement('label'); label.textContent = name + ' · path';
    const field = document.createElement('input'); field.dataset.parameter = name;
    field.value = input.pathParams?.[name] ?? ''; field.autocomplete = 'off'; field.spellcheck = false;
    field.addEventListener('input', preview); label.append(field); $('path-fields').append(label);
  }
  $('query').value = json(input.queryParams ?? {});
  $('body').value = json(input.body ?? {}); $('body-field').hidden = !bodyMethods.has(route.method)||input.bodyType==='form-data';
  const choices = $('client-payment-option'); choices.replaceChildren();
  if (offer.accepts.length > 1) {
    const placeholder = document.createElement('option'); placeholder.value = ''; placeholder.textContent = 'Choose a payment option';
    choices.append(placeholder);
  }
  offer.accepts.forEach((payment, index) => {
    const option = document.createElement('option'); option.value = String(index);
    option.textContent = `${index + 1}: ${payment.network} · ${payment.amount} atomic · ${payment.asset}`;
    choices.append(option);
  });
  choices.value = offer.accepts.length > 1 ? '' : '0';
  const required = (operation.parameters ?? []).filter(p => p.in === 'query' && p.required).map(p => p.name);
  text('required', required.length ? 'Required: ' + required.join(', ') : 'Omit unused optional parameters. Repeated values use JSON arrays of strings.');
  $('detail').hidden = false;
  for (const button of $('routes').children) button.setAttribute('aria-current', String(button.dataset.operation === operation.operationId));
  preview();
}
function renderRoutes() {
  const filter = $('filter').value.toLowerCase(); $('routes').replaceChildren();
  for (const operation of operations.filter(op => [op['x-seller-route'].method, op['x-seller-route'].path, op.summary].join(' ').toLowerCase().includes(filter))) {
    const button = document.createElement('button'); button.className = 'route'; button.dataset.operation = operation.operationId;
    button.setAttribute('aria-current', String(operation === current));
    const method = document.createElement('span'); method.className = 'method'; method.textContent = operation['x-seller-route'].method;
    const name = document.createElement('span'); name.className = 'route-name'; name.textContent = operation['x-seller-route'].path;
    button.append(method, name); button.addEventListener('click', () => choose(operation)); $('routes').append(button);
  }
  if (!$('routes').children.length) { const empty = document.createElement('p'); empty.className = 'hint'; empty.textContent = 'No matching endpoints.'; $('routes').append(empty); }
}
$('query').addEventListener('input', preview); $('body').addEventListener('input', preview);
$('client-payment-option').addEventListener('change', preview);
$('filter').addEventListener('input', renderRoutes);
const tabs = [...document.querySelectorAll('[data-tab]')];
function selectTab(button) {
  for (const tab of tabs) { const chosen = button === tab; tab.setAttribute('aria-selected', String(chosen)); tab.tabIndex = chosen ? 0 : -1; $(tab.dataset.tab + '-panel').hidden = !chosen; }
}
for (const [index, button] of tabs.entries()) {
  button.addEventListener('click', () => selectTab(button));
  button.addEventListener('keydown', event => {
    if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
    event.preventDefault();
    const target = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (index + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length;
    selectTab(tabs[target]); tabs[target].focus();
  });
}
selectTab(tabs[0]);
$('copy').addEventListener('click', async () => {
  if (!request) return;
  try { await navigator.clipboard.writeText(request.curl); $('copy').textContent = 'Copied'; }
  catch { const range = document.createRange(); range.selectNodeContents($('curl')); const selection = getSelection(); selection.removeAllRanges(); selection.addRange(range); $('copy').textContent = 'Select and copy'; }
  setTimeout(() => { $('copy').textContent = 'Copy curl'; }, 1800);
});
$('cancel').addEventListener('click', () => { invalidate(); setError('Request cancelled. No automatic retry.'); });
$('send').addEventListener('click', async () => {
  if (!request) return;
  invalidate(); const generation = revision, started = performance.now(); controller = new AbortController();
  const active = controller; const timer = setTimeout(() => active.abort(), 15000);
  $('send').disabled = true; $('cancel').hidden = false; setError('');
  try {
    const response = await fetch(request.url, { ...request.init, signal: active.signal });
    const body = await readLimitedResponse(response);
    if (generation !== revision) return;
    text('status', `HTTP ${response.status} · ${response.statusText}`);
    text('elapsed', `${Math.round(performance.now() - started)} ms`);
    text('headers', [...response.headers].map(([key, value]) => key + ': ' + value).join('\n'));
    text('response-body', body || '(empty response body)');
    $('response-payment-options-panel').hidden = true;
    try {
      const challenge = decodePaymentRequired(response.headers.get('payment-required'));
      text('challenge', json(challenge));
      if (Array.isArray(challenge?.accepts) && challenge.accepts.length) {
        text('response-payment-options-count', optionCount(renderPaymentOptions('response-payment-options', challenge.accepts)));
        $('response-payment-options-panel').hidden = false;
      }
    }
    catch (error) { text('challenge', error.message); }
    text('result-note', response.status === 402 ? 'Payment requirements received. No payment was signed or sent. These are the actual request-specific terms.' : 'An unpaid response was received. This does not establish successful payment or delivery; inspect the status and body.');
    $('result').hidden = false;
  } catch (error) {
    if (generation === revision) setError(active.signal.aborted ? 'Request timed out or was cancelled. No automatic retry.' : error.message);
  } finally {
    clearTimeout(timer);
    if (generation === revision) { controller = null; $('cancel').hidden = true; $('send').disabled = !request; }
  }
});
window.addEventListener('beforeunload', () => controller?.abort());
try {
  const response = await fetch('/_seller/openapi.json', { credentials: 'omit', redirect: 'error', cache: 'no-store', signal: AbortSignal.timeout(15000) });
  if (!response.ok) throw new Error(`Documentation unavailable: HTTP ${response.status}`);
  documentSpec = JSON.parse(await readLimitedResponse(response, 16 * 1024 * 1024));
  if (documentSpec.openapi !== '3.1.1' || !documentSpec.paths) throw new Error('Unsupported seller document');
  operations = Object.values(documentSpec.paths).flatMap(item => Object.values(item)).filter(op => op?.['x-seller-route']);
  if (!operations.length) throw new Error('No configured operations');
  text('title', documentSpec.info.title); document.title = documentSpec.info.title + ' · Starforge';
  text('mode', documentSpec['x-seller-runtime'] === 'NATIVE_X402' ? 'Native x402 runtime' : 'Challenge-only runtime');
  text('origin', documentSpec.servers[0].url); text('count', String(operations.length));
  renderRoutes(); choose(operations[0]);
} catch (error) { text('fatal', error.message); $('fatal').hidden = false; }

/* MIT. Local assets only; responsive seller developer workspace. */
:root{color-scheme:light;--ink:#182b32;--muted:#5c7178;--line:#dce6e7;--paper:#f4f8f7;--green:#0b6a58;--mint:#e6f3eb;--white:#fff;--mono:ui-monospace,SFMono-Regular,Consolas,monospace;font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif;color:var(--ink);background:var(--paper)}
*{box-sizing:border-box}
body{margin:0}
a{color:var(--green)}
button,input,textarea,select{font:inherit}
button,a,input,textarea,select,summary{outline-offset:4px}
button{cursor:pointer;border:1px solid var(--line);border-radius:8px;background:var(--white);color:var(--ink);padding:10px 14px}
button:disabled{cursor:wait;opacity:.6}
button:hover:not(:disabled){border-color:var(--green)}
[hidden]{display:none!important}
.top{display:flex;align-items:center;gap:24px;min-height:80px;padding:20px 5%;border-bottom:1px solid var(--line);background:var(--white)}
.brand{text-decoration:none;display:flex;gap:12px;align-items:center;font-size:28px;font-weight:800;color:var(--green)}
.brand span{font-size:15px;letter-spacing:.16em;color:var(--ink)}
.eyebrow,.label{font-size:10px;font-weight:750;letter-spacing:.12em;color:var(--muted)}
.top .download{margin-left:auto;font-size:13px;text-decoration:none;font-weight:650}
main{max-width:1320px;margin:auto;padding:0 40px}
.hero{display:flex;justify-content:space-between;align-items:center;gap:24px;padding:43px 0 29px}
.hero h1{font-size:clamp(26px,3vw,39px);letter-spacing:-.04em;line-height:1.13;margin:13px 0}
.intro{color:var(--muted);font-size:15px;line-height:1.6;margin:0;max-width:650px}
.runtime{display:flex;align-items:center;gap:9px;font-size:12px;border:1px solid var(--line);border-radius:30px;padding:11px 16px;white-space:nowrap;background:var(--white)}
.dot{height:7px;width:7px;border-radius:50%;background:var(--green)}
.overview{display:grid;grid-template-columns:2fr 1fr 1fr;border:1px solid var(--line);border-radius:12px;background:var(--white);margin-bottom:28px;overflow:hidden}
.overview>div{padding:19px 24px;display:flex;flex-direction:column;gap:9px;min-width:0}
.overview>div+div{border-left:1px solid var(--line)}
code{font-family:var(--mono);overflow-wrap:anywhere;font-size:12px}
.overview strong{font-size:17px;font-weight:650}
.workspace{display:grid;grid-template-columns:255px minmax(0,1fr);gap:28px}
.workspace aside{padding:8px 0}
.workspace article{border:1px solid var(--line);border-radius:12px;background:var(--white);padding:28px;min-width:0}
input,textarea{border:1px solid var(--line);border-radius:7px;background:var(--white);color:var(--ink);width:100%;padding:11px 12px}
#client-payment-option{display:block;width:100%;min-width:0;max-width:100%;border:1px solid var(--line);background:var(--white);color:var(--ink);padding:10px;font-size:12px}
input:focus,textarea:focus{outline:2px solid #91bcb0}
input[type=search]{margin-top:12px;margin-bottom:15px;font-size:12px}
textarea{font-family:var(--mono);font-size:12px;line-height:1.65;resize:vertical}
nav{display:grid;gap:8px}
.route{display:flex;align-items:start;text-align:left;gap:9px;padding:13px 11px;background:transparent;border-color:transparent;overflow:hidden}
.route[aria-current=true]{background:var(--mint);border-color:#bcd8ca}
.route .route-name{overflow-wrap:anywhere;font-family:var(--mono);font-size:12px;line-height:1.6}
.method{display:inline-block;font:700 10px var(--mono);color:var(--green);background:var(--mint);border:1px solid #c8dfd2;border-radius:5px;padding:5px 7px;letter-spacing:.03em;flex:none}
.route .method{padding:3px 5px;min-width:42px;text-align:center}
.aside-note{font-size:11px;line-height:1.7;color:var(--muted);padding:18px 9px;max-width:245px}
.endpoint-heading{display:flex;align-items:center;gap:13px}
.endpoint-heading h2{font:600 21px var(--mono);margin:0;overflow-wrap:anywhere}
.description{font-size:14px;line-height:1.6;color:var(--muted);margin:15px 0 20px}
.terms{display:grid;grid-template-columns:1fr 1fr;background:var(--paper);border:1px solid var(--line);border-radius:8px}
.terms>div{display:flex;flex-direction:column;gap:8px;padding:18px}
.terms strong{font-size:19px;font-weight:600;overflow-wrap:anywhere}
.terms small{color:var(--muted);font-size:11px}
.terms>div+div{border-left:1px solid var(--line)}
details{font-size:12px;margin-top:15px}
summary{cursor:pointer;color:var(--muted);font-weight:600;padding:6px 0}
dl{display:grid;grid-template-columns:70px 1fr;gap:10px;padding:12px 0}
dt{color:var(--muted)}
dd{margin:0;overflow-wrap:anywhere;font-family:var(--mono);font-size:11px}
.terms-detail p{color:var(--muted);line-height:1.5;font-size:11px}
.tabs{display:flex;gap:17px;border-bottom:1px solid var(--line);margin:25px 0 21px}
.tabs button{border:0;border-bottom:2px solid transparent;border-radius:0;padding:13px 0;font-size:12px;color:var(--muted)}
.tabs button[aria-selected=true]{border-bottom-color:var(--green);color:var(--green);font-weight:700}
.field-label{display:block;font-size:12px;font-weight:650;margin:18px 0 8px}
.field-label span{font-weight:400;color:var(--muted);font-size:11px;float:right}
.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:15px}
.fields label{font-size:12px;font-weight:600}
.fields input{font-family:var(--mono);font-size:12px;margin-top:8px}
.hint{font-size:11px;line-height:1.7;color:var(--muted);overflow-wrap:anywhere}
.preview{margin-top:22px;border:1px solid var(--line);border-radius:8px;overflow:hidden}
.preview-heading{display:flex;align-items:center;justify-content:space-between;padding:9px 14px;background:var(--paper)}
pre{font:12px/1.7 var(--mono);white-space:pre-wrap;overflow-wrap:anywhere;margin:0;padding:18px;background:#f7faf9;border-radius:7px;max-height:620px;overflow:auto}
.preview pre{background:var(--white);font-size:11px}
.quiet{font-size:11px;padding:6px 10px;background:transparent}
.execution{display:flex;align-items:center;flex-wrap:wrap;gap:14px;margin-top:21px}
.execution>div{flex:1 0 100%;display:flex;flex-direction:column;gap:8px}
.execution p{font-size:11px;color:var(--muted);margin:0;line-height:1.65}
.primary{background:var(--green);color:var(--white);font-size:12px;padding:13px 19px;font-weight:600}
.error{border:1px solid #dbbeb6;background:#fff1ed;color:#873d2b;font-size:13px;line-height:1.5;padding:14px;border-radius:8px;margin:16px 0;overflow-wrap:anywhere}
.result{border-top:1px solid var(--line);padding-top:22px;margin-top:27px}
.result-heading{display:flex;justify-content:space-between;align-items:center}
.result h3{font-size:16px;margin:0}
.result-heading span{font:11px var(--mono);color:var(--muted)}
.result p{font-size:12px;line-height:1.7;color:var(--muted)}
.result h4{font-size:11px;letter-spacing:.03em;color:var(--muted);margin-top:20px}
footer{font-size:11px;color:var(--muted);line-height:1.7;padding:27px 0 40px;display:flex;gap:18px;flex-wrap:wrap}
footer a:first-of-type{margin-left:auto}
.payment-options-heading{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin:18px 0 10px}
.payment-options-heading h3{font-size:14px;font-weight:650;margin:0}
.payment-options-heading>span{font:11px var(--mono);color:var(--muted);white-space:nowrap}
.payment-options{display:grid;gap:12px;margin:12px 0}
.payment-option{border:1px solid #d8dcdf;border-radius:4px;padding:15px;background:#fff;min-width:0}
.payment-option-heading{display:flex;align-items:baseline;justify-content:space-between;gap:16px;border-bottom:1px solid #e6e8ea;padding-bottom:12px;margin-bottom:12px}
.payment-option-heading h4{font-size:12px;font-weight:650;margin:0;color:var(--ink)}
.payment-option-price{display:flex;align-items:baseline;justify-content:flex-end;flex-wrap:wrap;gap:6px 10px;min-width:0;text-align:right}
.payment-option-price strong{font:600 15px var(--mono);overflow-wrap:anywhere}
.payment-option-price small{font-size:10px;color:var(--muted)}
.payment-option dl{grid-template-columns:112px minmax(0,1fr);gap:9px 14px;padding:0;margin:0;font-size:11px;line-height:1.5}
.payment-option dd{font-size:11px}
.payment-option-extra-label{font-size:10px;font-weight:650;color:var(--muted);margin:13px 0 6px}
.payment-option-extra{background:#f5f6f7;border-radius:3px;padding:10px;font-size:11px;max-height:none}
@media(max-width:850px){main{padding:0 20px}
.top{gap:10px;padding:18px 20px}
.top>.eyebrow{display:none}
.hero{align-items:flex-start;flex-direction:column;padding-top:28px}
.workspace{grid-template-columns:1fr;gap:10px}
.workspace aside{display:block}
nav{grid-template-columns:repeat(auto-fit,minmax(175px,1fr));max-height:220px;overflow:auto}
.aside-note{display:none}
.workspace article{padding:20px}
.overview>div{padding:16px 13px}
.overview{grid-template-columns:1.4fr 1fr}
.overview>div:last-child{display:none}
.field-label span{float:none;display:block;margin-top:5px}
.endpoint-heading h2{font-size:17px}
.terms strong{font-size:15px}
.brand span{font-size:12px}
.top .download{font-size:11px}
footer a:first-of-type{margin-left:0}
}
@media(max-width:480px){.payment-option{padding:12px}.payment-option-heading{align-items:flex-start;gap:10px}.payment-option-price{display:block}.payment-option-price small{display:block;margin-top:4px}.payment-option dl{grid-template-columns:84px minmax(0,1fr);gap:8px 10px}.payment-option-price strong{font-size:13px}}

// MIT. Original subscription operator; requests are captured before controls become busy.
const $=id=>document.getElementById(id),content=$('content');let status,tab='publishers',busy=false;
const selected={publisher:null,customer:null};let retryKey;
function el(tag,text,attrs={}){const node=document.createElement(tag);if(text!==undefined&&text!==null)node.textContent=String(text);for(const [key,value]of Object.entries(attrs))node.setAttribute(key,value);return node;}
function append(parent,...children){parent.append(...children.filter(Boolean));return parent;}
function panel(title,...children){return append(el('section',null,{class:'panel'}),el('h2',title),...children);}
function note(text){return el('p',text,{class:'muted'});}
function button(text,fn,primary=false){const b=el('button',text,{type:'button',...(primary?{class:'primary'}:{})});b.onclick=fn;return b;}
function json(value){return JSON.stringify(value,null,2);}
function setBusy(value){busy=value;document.querySelectorAll('button,input,select,textarea').forEach(n=>n.disabled=value);}
function message(value,error=false){$('message').textContent=value;$('message').className=error?'error':'';}
async function api(operation,args={}){
 const response=await fetch('./api/operate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation,args})});
 const value=await response.json();if(!response.ok)throw Object.assign(new Error(value.message||'The original operation did not complete.'),{code:value.error});return value;
}
function showResult(value){$('result').textContent=json(value);$('receipt').open=true;}
function retryView(){
 $('retry').replaceChildren();if(!retryKey)return;
 let value;try{value=JSON.parse(localStorage.getItem(retryKey)||'null');}catch{}
 if(value)append($('retry'),el('strong','Selected request: '+value.operation+' '),note('Continue this exact request after an interruption. Its original IDs and edition selection remain unchanged.'),button('Retry selected request',()=>perform(value.operation,value.args)));
}
async function perform(operation,args){
 if(busy)return;const request={operation,args:JSON.parse(JSON.stringify(args))};
 localStorage.setItem(retryKey,json(request));retryView();setBusy(true);message('Running '+operation+'…');
 try{const result=await api(operation,request.args);showResult(result);localStorage.removeItem(retryKey);message('Completed '+operation+'.');retryView();await render();return result;}
 catch(error){message((error.code?error.code+': ':'')+error.message,true);}
 finally{setBusy(false);}
}
function field(form,name,label,{value='',type='text',options,required=true,description}={}){
 const labelNode=el('label',label);let input;
 if(options){input=el('select',null,{name});for(const [v,t]of options)input.append(el('option',t,{value:v}));input.value=String(value);}
 else if(type==='textarea'){input=el('textarea',value,{name});}
 else{input=el('input',null,{name,type});if(type==='checkbox')input.checked=value===true;else input.value=value;}
 if(required&&type!=='checkbox')input.required=true;
 append(form,labelNode,input,description?note(description):null);return input;
}
function form(title,operation,build,read){
