.postgres-staging{border:1px solid #c9c9c7;background:#fff;padding:18px 22px;margin-bottom:20px;min-width:0}.postgres-staging>summary{font-weight:600;cursor:pointer}.postgres-staging[open]>summary{margin-bottom:16px}.postgres-staging p{font-size:12px}.postgres-contract{min-width:0}.postgres-contract details{border-top:1px solid #dededb;margin:10px 0;padding-top:10px}.postgres-contract summary{cursor:pointer;overflow-wrap:anywhere}.postgres-contract details[open]>summary{margin-bottom:12px}.postgres-fields{display:grid;grid-template-columns:minmax(130px,190px) minmax(0,1fr);gap:7px 14px;font-size:12px;line-height:1.5}.postgres-fields dt{color:#606264}.postgres-fields dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.postgres-contract td{white-space:pre-wrap;overflow-wrap:anywhere;min-width:100px}.postgres-staging .check-label{display:flex;align-items:center;gap:9px}.check-label input[type=checkbox]{width:auto;margin:0}.postgres-staging section{margin-top:20px}.postgres-contract p{font-size:12px}summary:focus-visible,a:focus-visible,select:focus-visible{outline:2px solid #202124;outline-offset:3px}@media(max-width:680px){.postgres-staging{padding:18px}.postgres-fields{grid-template-columns:1fr;gap:4px}.postgres-fields dd{margin-bottom:8px}.postgres-staging button{white-space:normal}}

.client-operations { background: var(--surface, #fff); border: 1px solid var(--line, #d5d7db); padding: 24px; margin-top: 20px; min-width: 0; overflow-wrap: anywhere; }
.client-operations .fields { max-width: 480px; margin-bottom: 12px; }
.client-operations td, .client-operations dd, .client-operations code { overflow-wrap: anywhere; }
.client-operations td { vertical-align: top; }
.client-operations table { min-width: 680px; }
.client-operations th { overflow-wrap: normal; }
.client-operation table { min-width: 800px; }
.client-operation td:nth-child(2) { white-space: nowrap; }
.client-operations pre { white-space: pre-wrap; overflow-wrap: anywhere; }
.client-operations #client-notice:empty { display: none; }
.client-operation { border-top: 1px solid var(--line, #d5d7db); padding-top: 12px; margin: 20px 0; }
.client-operation h4 { margin: 0 0 12px; }
#client-review { margin-top: 24px; }
#client-files code { display: block; max-width: 38rem; font-size: 12px; }
@media (max-width: 700px) { .client-operations { padding: 16px; } .client-operations .section-heading { align-items: flex-start; flex-direction: column; } }

.delivery-operations{background:#fff;border:1px solid #c9c9c7;margin-top:22px;padding:23px 26px;min-width:0}
.delivery-operations p,.delivery-operations pre,.delivery-operations td{overflow-wrap:anywhere}
.delivery-operations p{font-size:12px;line-height:1.55}.delivery-operations h3{margin-top:24px}
.delivery-operations table{table-layout:fixed;width:100%;min-width:620px}.delivery-operations .table-scroll{max-width:100%;overflow:auto;margin:16px 0}
.delivery-operations td>div>div{font-size:11px;margin-top:4px}
.delivery-operations .actions a{color:inherit;font-size:12px;font-weight:600;border:1px solid #9d9e9f;border-radius:3px;padding:9px 11px;display:inline-flex;align-items:center;min-height:36px}
.delivery-operations details{margin-top:18px}.delivery-operations summary{cursor:pointer;font-weight:600;font-size:12px}
.delivery-operations pre{white-space:pre-wrap;font:12px/1.6 ui-monospace,SFMono-Regular,Consolas,monospace;background:#f5f5f4;border:1px solid #ddd;padding:12px;max-width:100%}
.delivery-operations #delivery-review{margin-top:22px;padding-top:2px;border-top:1px solid #c9c9c7}
.delivery-operations .section-note{color:#55585a}.delivery-operations [hidden]{display:none!important}
@media(max-width:680px){.delivery-operations{padding:20px;min-width:0}.delivery-operations .section-heading{display:block}.delivery-operations .section-heading>button{margin-top:8px}.delivery-operations .actions{align-items:stretch}.delivery-operations .actions a{justify-content:center}}
